class Document extends DataClass implements Insertable<Document> {
  final String id;
  final String projectId;
  final String name;
  final String category;
  final int version;

  /// Local on-device file path (copied into the app's documents dir by
  /// file_picker), same pattern as DprPhotos.photoPath.
  final String filePath;
  final int? fileSize;
  final String? mimeType;
  final String? notes;
  final String uploadedBy;
  final DateTime createdAt;
  const Document({
    required this.id,
    required this.projectId,
    required this.name,
    required this.category,
    required this.version,
    required this.filePath,
    this.fileSize,
    this.mimeType,
    this.notes,
    required this.uploadedBy,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['project_id'] = Variable<String>(projectId);
    map['name'] = Variable<String>(name);
    map['category'] = Variable<String>(category);
    map['version'] = Variable<int>(version);
    map['file_path'] = Variable<String>(filePath);
    if (!nullToAbsent || fileSize != null) {
      map['file_size'] = Variable<int>(fileSize);
    }
    if (!nullToAbsent || mimeType != null) {
      map['mime_type'] = Variable<String>(mimeType);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['uploaded_by'] = Variable<String>(uploadedBy);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  DocumentsCompanion toCompanion(bool nullToAbsent) {
    return DocumentsCompanion(
      id: Value(id),
      projectId: Value(projectId),
      name: Value(name),
      category: Value(category),
      version: Value(version),
      filePath: Value(filePath),
      fileSize: fileSize == null && nullToAbsent
          ? const Value.absent()
          : Value(fileSize),
      mimeType: mimeType == null && nullToAbsent
          ? const Value.absent()
          : Value(mimeType),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      uploadedBy: Value(uploadedBy),
      createdAt: Value(createdAt),
    );
  }

  factory Document.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Document(
      id: serializer.fromJson<String>(json['id']),
      projectId: serializer.fromJson<String>(json['projectId']),
      name: serializer.fromJson<String>(json['name']),
      category: serializer.fromJson<String>(json['category']),
      version: serializer.fromJson<int>(json['version']),
      filePath: serializer.fromJson<String>(json['filePath']),
      fileSize: serializer.fromJson<int?>(json['fileSize']),
      mimeType: serializer.fromJson<String?>(json['mimeType']),
      notes: serializer.fromJson<String?>(json['notes']),
      uploadedBy: serializer.fromJson<String>(json['uploadedBy']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'projectId': serializer.toJson<String>(projectId),
      'name': serializer.toJson<String>(name),
      'category': serializer.toJson<String>(category),
      'version': serializer.toJson<int>(version),
      'filePath': serializer.toJson<String>(filePath),
      'fileSize': serializer.toJson<int?>(fileSize),
      'mimeType': serializer.toJson<String?>(mimeType),
      'notes': serializer.toJson<String?>(notes),
      'uploadedBy': serializer.toJson<String>(uploadedBy),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  Document copyWith({
    String? id,
    String? projectId,
    String? name,
    String? category,
    int? version,
    String? filePath,
    Value<int?> fileSize = const Value.absent(),
    Value<String?> mimeType = const Value.absent(),
    Value<String?> notes = const Value.absent(),
    String? uploadedBy,
    DateTime? createdAt,
  }) => Document(
    id: id ?? this.id,
    projectId: projectId ?? this.projectId,
    name: name ?? this.name,
    category: category ?? this.category,
    version: version ?? this.version,
    filePath: filePath ?? this.filePath,
    fileSize: fileSize.present ? fileSize.value : this.fileSize,
    mimeType: mimeType.present ? mimeType.value : this.mimeType,
    notes: notes.present ? notes.value : this.notes,
    uploadedBy: uploadedBy ?? this.uploadedBy,
    createdAt: createdAt ?? this.createdAt,
  );
  Document copyWithCompanion(DocumentsCompanion data) {
    return Document(
      id: data.id.present ? data.id.value : this.id,
      projectId: data.projectId.present ? data.projectId.value : this.projectId,
      name: data.name.present ? data.name.value : this.name,
      category: data.category.present ? data.category.value : this.category,
      version: data.version.present ? data.version.value : this.version,
      filePath: data.filePath.present ? data.filePath.value : this.filePath,
      fileSize: data.fileSize.present ? data.fileSize.value : this.fileSize,
      mimeType: data.mimeType.present ? data.mimeType.value : this.mimeType,
      notes: data.notes.present ? data.notes.value : this.notes,
      uploadedBy: data.uploadedBy.present
          ? data.uploadedBy.value
          : this.uploadedBy,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Document(')
          ..write('id: $id, ')
          ..write('projectId: $projectId, ')
          ..write('name: $name, ')
          ..write('category: $category, ')
          ..write('version: $version, ')
          ..write('filePath: $filePath, ')
          ..write('fileSize: $fileSize, ')
          ..write('mimeType: $mimeType, ')
          ..write('notes: $notes, ')
          ..write('uploadedBy: $uploadedBy, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    projectId,
    name,
    category,
    version,
    filePath,
    fileSize,
    mimeType,
    notes,
    uploadedBy,
    createdAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Document &&
          other.id == this.id &&
          other.projectId == this.projectId &&
          other.name == this.name &&
          other.category == this.category &&
          other.version == this.version &&
          other.filePath == this.filePath &&
          other.fileSize == this.fileSize &&
          other.mimeType == this.mimeType &&
          other.notes == this.notes &&
          other.uploadedBy == this.uploadedBy &&
          other.createdAt == this.createdAt);
}

